<?= view('web/_layout_top', get_defined_vars()) ?>
<?php $modalToOpen = (string) (session('modal') ?: (old('_modal_context') === 'create-location' ? 'create-location-modal' : '')); ?>
<section class="card">
  <div class="cms-page-toolbar"><div><p>LOCATION DIRECTORY</p><h2>Locations and Studios</h2><span>Organize cinema sites, then manage the Studios inside each Location.</span></div><div class="cms-toolbar-actions"><span class="count"><?= count($locations) ?> Locations</span><button class="btn primary" type="button" data-cms-modal-open="create-location-modal">+ Add Location</button></div></div>
  <form method="get" action="<?= site_url('control/locations') ?>" class="filter-row"><input name="q" value="<?= esc($filters['q']) ?>" placeholder="Search name, code, or address"><select name="status"><option value="">All statuses</option><option value="active" <?= $filters['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $filters['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select><button class="btn primary" type="submit">Apply filters</button><a class="btn ghost" href="<?= site_url('control/locations') ?>">Reset</a></form>
  <?php if ($locations === []): ?><div class="empty">No Locations match the current filters.</div><?php else: ?><div class="location-grid">
  <?php foreach ($locations as $item): $location = $item['entity']; $modalKey = preg_replace('/[^A-Za-z0-9_-]/', '-', $location->public_id); ?>
    <article class="location-card"><div class="location-head"><div><span class="location-code"><?= esc($location->code) ?></span><h3><?= esc($location->name) ?></h3><p><?= esc($location->address ?: $location->timezone) ?></p></div><span class="badge <?= esc($location->status) ?>"><?= esc(strtoupper($location->status)) ?></span></div><div class="location-stats"><span><strong><?= $item['total'] ?></strong><small>Studios</small></span><span><strong><?= $item['online'] ?></strong><small>Online</small></span><span><strong><?= $item['playing'] ?></strong><small>Playing</small></span><span class="<?= $item['errors'] > 0 ? 'has-error' : '' ?>"><strong><?= $item['errors'] ?></strong><small>Errors</small></span></div><div class="studio-list"><?php if ($item['studios'] === []): ?><p class="muted">No Studios assigned.</p><?php endif ?><?php foreach (array_slice($item['studios'], 0, 4) as $studio): $device = $studio['entity']; ?><a href="<?= site_url('control/locations/' . rawurlencode($location->public_id)) ?>"><span><strong><?= esc($device->name) ?></strong><small><?= esc(ucfirst($device->playback_state ?: 'unknown')) ?></small></span><span class="badge <?= esc($studio['connection']) ?>"><?= esc(strtoupper($studio['connection'])) ?></span></a><?php endforeach ?><?php if (count($item['studios']) > 4): ?><p class="muted">+ <?= count($item['studios']) - 4 ?> more Studios</p><?php endif ?></div><div class="location-card-actions"><a class="btn primary" href="<?= site_url('control/locations/' . rawurlencode($location->public_id)) ?>">Manage Studios</a><a class="btn ghost" href="<?= site_url('control/locations/' . rawurlencode($location->public_id) . '#add-studio') ?>">Add Studio</a><button class="btn ghost" type="button" data-cms-modal-open="edit-location-<?= esc($modalKey, 'attr') ?>">Edit</button></div><div class="location-secondary-actions"><button class="btn ghost" type="button" data-cms-modal-open="status-location-<?= esc($modalKey, 'attr') ?>"><?= $location->status === 'active' ? 'Deactivate' : 'Activate' ?></button><?php if ($location->status === 'inactive' && $item['total'] === 0): ?><button class="btn danger" type="button" data-cms-modal-open="delete-location-<?= esc($modalKey, 'attr') ?>">Delete</button><?php endif ?></div></article>
    <dialog class="cms-action-modal" id="edit-location-<?= esc($modalKey, 'attr') ?>" data-cms-modal <?= $modalToOpen === 'edit-location-' . $modalKey ? 'data-auto-open="true"' : '' ?>><form method="post" action="<?= site_url('control/locations/' . rawurlencode($location->public_id) . '/update') ?>" class="cms-modal-shell cms-modal-form"><?= csrf_field() ?><input type="hidden" name="_modal_context" value="edit-location-<?= esc($modalKey, 'attr') ?>"><header class="cms-modal-header"><div><p>LOCATION SETTINGS</p><h2>Edit <?= esc($location->name) ?></h2><span>Update the identity and timezone inherited by its Studios.</span></div><button class="cms-modal-x" type="button" data-cms-modal-close aria-label="Close">×</button></header><div class="cms-modal-body cms-form-grid"><label>Location name<input name="name" value="<?= esc($location->name) ?>" maxlength="160" required autofocus></label><label>Code<input name="code" value="<?= esc($location->code) ?>" maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9-]{0,23}" required></label><label>Timezone<input name="timezone" value="<?= esc($location->timezone) ?>" required></label><label>Address<input name="address" value="<?= esc($location->address) ?>" maxlength="1000"></label><input type="hidden" name="status" value="<?= esc($location->status) ?>"></div><footer class="cms-modal-footer"><span>Existing Studio overrides are not changed.</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn primary" type="submit">Save Location</button></div></footer></form></dialog>
    <dialog class="cms-action-modal" id="status-location-<?= esc($modalKey, 'attr') ?>" data-cms-modal><form method="post" action="<?= site_url('control/locations/' . rawurlencode($location->public_id) . '/status') ?>" class="cms-modal-shell"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $location->status === 'active' ? 'inactive' : 'active' ?>"><header class="cms-modal-header"><div><p>LOCATION LIFECYCLE</p><h2><?= $location->status === 'active' ? 'Deactivate' : 'Activate' ?> <?= esc($location->name) ?>?</h2></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body"><div class="cms-confirm-message <?= $location->status === 'active' ? 'danger' : '' ?>"><strong><?= $location->status === 'active' ? 'New Studio creation and pairing will be blocked.' : 'This Location will accept Studio activity again.' ?></strong><?= $location->status === 'active' ? 'Existing records remain stored and can be reactivated later.' : 'Its current Studios keep their existing assignments.' ?></div></div><footer class="cms-modal-footer"><span>Location status change</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn <?= $location->status === 'active' ? 'danger' : 'primary' ?>" type="submit">Confirm <?= $location->status === 'active' ? 'Deactivation' : 'Activation' ?></button></div></footer></form></dialog>
    <?php if ($location->status === 'inactive' && $item['total'] === 0): ?><dialog class="cms-action-modal" id="delete-location-<?= esc($modalKey, 'attr') ?>" data-cms-modal><form method="post" action="<?= site_url('control/locations/' . rawurlencode($location->public_id) . '/delete') ?>" class="cms-modal-shell"><?= csrf_field() ?><header class="cms-modal-header"><div><p>DANGER ZONE</p><h2>Delete <?= esc($location->name) ?>?</h2></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body"><div class="cms-confirm-message danger"><strong>This action cannot be undone.</strong>The unused Location will be permanently removed from the CMS database.</div></div><footer class="cms-modal-footer"><span>Permanent deletion</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn danger" type="submit">Delete Location</button></div></footer></form></dialog><?php endif ?>
  <?php endforeach ?></div><?php endif ?>
</section>
<dialog class="cms-action-modal" id="create-location-modal" data-cms-modal <?= $modalToOpen === 'create-location-modal' ? 'data-auto-open="true"' : '' ?>><form method="post" action="<?= site_url('control/locations') ?>" class="cms-modal-shell cms-modal-form"><?= csrf_field() ?><input type="hidden" name="_modal_context" value="create-location"><header class="cms-modal-header"><div><p>ORGANIZATION</p><h2>Add a Location</h2><span>One Location can contain multiple Studios.</span></div><button class="cms-modal-x" type="button" data-cms-modal-close>×</button></header><div class="cms-modal-body cms-form-grid"><label>Location name<input name="name" value="<?= esc(old('name')) ?>" maxlength="160" placeholder="Bogor" required autofocus></label><label>Code<input name="code" value="<?= esc(old('code')) ?>" maxlength="24" placeholder="BGR" pattern="[A-Za-z0-9][A-Za-z0-9-]{0,23}" required></label><label>Timezone<input name="timezone" value="<?= esc(old('timezone') ?: 'Asia/Jakarta') ?>" required></label><label>Address <span class="muted">(optional)</span><input name="address" value="<?= esc(old('address')) ?>" maxlength="1000" placeholder="Mall, street, city"></label></div><footer class="cms-modal-footer"><span>Studios can be added immediately after creation.</span><div><button class="btn ghost" type="button" data-cms-modal-close>Cancel</button><button class="btn primary" type="submit">Create Location</button></div></footer></form></dialog>
<?= view('web/_layout_bottom') ?>
